var AVBS_OOPS = {};
const avbsOops = function (where, err) { if (!AVBS_OOPS[where]) { AVBS_OOPS[where] = true; console.error('[avgustov] boss hook ' + where + ' failed: ' + err); } };
// KubeJS gives entity.getType() as the id string; fall back to the registry for raw entities
const avbsId = function (ent) { var t = ent.getType(), s = String(t); return (s.indexOf(':') > 0 && s.indexOf(' ') < 0) ? s : String(AVBS_EntityType.getKey(t)); };
// KubeJS exposes Entity.level as a property, not a method (calling level() throws): accept both
const avbsLevel = function (ent) { var l = ent.level; return (typeof l === 'function') ? ent.level() : l; };
const avbsSetBase = function (ent, attr, v) { var a = ent.getAttribute(attr); if (a && v !== null && v !== undefined) a.setBaseValue(v); };
// the entity behind a damage source (KubeJS helpers first, vanilla names as fallback)
const avbsCauser = function (src) {
  var a = null;
  try { a = src.getActual(); } catch (x) {}
  if (!a) try { a = src.getEntity(); } catch (x) {}
  return a;
};
// damage type id, e.g. "minecraft:arrow" (getRegisteredName never throws; "[unregistered]" for odd sources)
const avbsTypeId = function (src) { try { return String(src.typeHolder().getRegisteredName()); } catch (x) { return ''; } };
// the projectile or other entity that touched the boss
const avbsDirect = function (src) {
  var d = null;
  try { d = src.getImmediate(); } catch (x) {}
  if (!d) try { d = src.getDirectEntity(); } catch (x) {}
  return d;
};
// vanilla #minecraft:is_explosion members (the tag itself cannot be checked safely from here, see above)
const AVBS_EXPLOSION = { 'minecraft:explosion': 1, 'minecraft:player_explosion': 1, 'minecraft:fireworks': 1, 'minecraft:bad_respawn_point': 1 };

EntityEvents.spawned(function (e) {
  var ent = e.entity; if (!ent || !ent.isLiving()) return;
  try {
    var b = AVBS[avbsId(ent)]; if (!b) return;
    if (!b.cfg) {
      avbsSetBase(ent, AVBS_Attributes.MAX_HEALTH, b.hp);
      if (b.atk !== null) avbsSetBase(ent, AVBS_Attributes.ATTACK_DAMAGE, b.atk);
      avbsSetBase(ent, AVBS_Attributes.ARMOR, b.armor);
    }
    var pd = ent.persistentData;
    if (!pd.getBoolean('avBoss')) { pd.putBoolean('avBoss', true); ent.setHealth(ent.getMaxHealth()); }
  } catch (err) { avbsOops('spawn', err); }
});

// per boss+attacker gun damage in the current second: key -> [second, sum]
const AVBS_WINDOW = {};
NativeEvents.onEvent(AVBS_Incoming, function (e) {
 try {
  var victim = e.getEntity(), src = e.getSource();
  // 1. damage dealt BY a boss to a player
  if (victim instanceof AVBS_Player) {
    var c = avbsCauser(src); if (!c) return;
    var bo = AVBS[avbsId(c)];
    if (bo && bo.out !== 1) e.setAmount(e.getAmount() * bo.out);
    return;
  }
  // 2. damage dealt TO a boss
  var b = AVBS[avbsId(victim)]; if (!b) return;
  var typeId = avbsTypeId(src), attacker = avbsCauser(src);
  if (!(attacker instanceof AVBS_Player)) attacker = null;
  if (attacker && b.party) {
    var n = 0;
    var lvl = avbsLevel(victim), pl = lvl.players; if (typeof pl === 'function') pl = lvl.players();
    pl.forEach(function (p) { if (!p.isSpectator() && p.distanceToSqr(victim) <= 4096) n++; });
    n = Math.max(1, Math.min(4, n));
    var pd = victim.persistentData, had = pd.getInt('avParty') || 1;
    if (n > had) {
      var frac = victim.getHealth() / victim.getMaxHealth();
      var attr = victim.getAttribute(AVBS_Attributes.MAX_HEALTH);
      // 1.2.3: removeModifier(id) is ambiguous for Rhino and threw here, so party scaling never applied
      attr.addOrReplacePermanentModifier(new AVBS_Modifier(AVBS_PARTY_ID, 0.35 * (n - 1), AVBS_Op.ADD_MULTIPLIED_BASE));
      victim.setHealth(Math.max(1, frac * victim.getMaxHealth()));
      pd.putInt('avParty', n);
    }
  }
  var amount = e.getAmount();
  var cannon = typeId.indexOf('createbigcannons:') === 0 || typeId === 'ntgl:explosive' || AVBS_EXPLOSION[typeId] === 1 || typeId.indexOf('explosion') >= 0;
  var gun = !cannon && (typeId.indexOf('ntgl:') === 0 || avbsDirect(src) instanceof AVBS_Projectile);
  if (b.hit && cannon && amount > b.hit) amount = b.hit;
  if (b.dps && gun) {
    var key = victim.getStringUUID() + (attacker ? attacker.getStringUUID() : 'world'), sec = Math.floor(avbsLevel(victim).getGameTime() / 20);
    var w = AVBS_WINDOW[key]; if (!w || w[0] !== sec) { w = [sec, 0]; AVBS_WINDOW[key] = w; }
    var room = Math.max(0, b.dps - w[1]); if (amount > room) amount = room;
    w[1] += amount;
  }
  if (amount !== e.getAmount()) e.setAmount(amount);
 } catch (err) { avbsOops('damage', err); }
});
